import os
import queue
import sys
import threading
from typing import Iterator, Optional

import azure.cognitiveservices.speech as speechsdk
from azure.cognitiveservices.speech import AudioStreamFormat, PushAudioInputStream


class StreamingMicrophoneTranscriber:
    def __init__(
        self,
        language: str = "en-US",
        sample_rate: int = 16000,
        channels: int = 1,
        chunk_size: int = 3200,
    ):
        self.language = language
        self.sample_rate = sample_rate
        self.channels = channels
        self.chunk_size = chunk_size

        speech_key = os.environ.get("AZURE_SPEECH_KEY")
        speech_region = os.environ.get("AZURE_SPEECH_REGION")
        if not speech_key or not speech_region:
            raise EnvironmentError(
                "Set AZURE_SPEECH_KEY and AZURE_SPEECH_REGION environment variables."
            )

        self.speech_config = speechsdk.SpeechConfig(
            subscription=speech_key, region=speech_region
        )
        self.speech_config.speech_recognition_language = self.language

        self.audio_format = AudioStreamFormat(
            samples_per_second=self.sample_rate, bits_per_sample=16, channels=self.channels
        )
        self.push_stream = PushAudioInputStream(stream_format=self.audio_format)
        self.audio_config = speechsdk.AudioConfig(stream=self.push_stream)
        self.recognizer = speechsdk.SpeechRecognizer(
            speech_config=self.speech_config, audio_config=self.audio_config
        )

        self._transcript_queue: "queue.Queue[Optional[str]]" = queue.Queue()
        self._stop_event = threading.Event()
        self._mic_thread: Optional[threading.Thread] = None

        self.recognizer.recognizing.connect(self._on_recognizing)
        self.recognizer.recognized.connect(self._on_recognized)
        self.recognizer.canceled.connect(self._on_canceled)
        self.recognizer.session_stopped.connect(self._on_session_stopped)

    def _on_recognizing(self, evt: speechsdk.SpeechRecognitionEventArgs) -> None:
        text = getattr(evt.result, "text", "") or ""
        if text:
            self._transcript_queue.put(text)

    def _on_recognized(self, evt: speechsdk.SpeechRecognitionEventArgs) -> None:
        text = getattr(evt.result, "text", "") or ""
        if text:
            self._transcript_queue.put(text)

    def _on_canceled(self, evt: speechsdk.SpeechRecognitionCanceledEventArgs) -> None:
        reason = getattr(evt, "reason", None)
        details = getattr(evt, "error_details", None) or str(reason) or "Recognition canceled"
        self._transcript_queue.put(f"[canceled] {details}")
        self.stop()

    def _on_session_stopped(self, evt: speechsdk.SessionEventArgs) -> None:
        self.stop()

    def _read_mic_and_push(self) -> None:
        try:
            import sounddevice as sd
        except ImportError as exc:
            self._transcript_queue.put(
                "The 'sounddevice' package is required for microphone capture."
            )
            self.stop()
            raise exc

        def callback(indata, frames, time, status):
            if status:
                pass
            if not self._stop_event.is_set():
                self.push_stream.write(indata.tobytes())

        with sd.InputStream(
            samplerate=self.sample_rate,
            channels=self.channels,
            dtype="int16",
            blocksize=self.chunk_size // (2 * self.channels),
            callback=callback,
        ):
            while not self._stop_event.is_set():
                sd.sleep(50)

    def start(self) -> None:
        self._stop_event.clear()
        self.recognizer.start_continuous_recognition()
        self._mic_thread = threading.Thread(target=self._read_mic_and_push, daemon=True)
        self._mic_thread.start()

    def stop(self) -> None:
        if not self._stop_event.is_set():
            self._stop_event.set()
            try:
                self.push_stream.close()
            except Exception:
                pass
            try:
                self.recognizer.stop_continuous_recognition()
            except Exception:
                pass
            self._transcript_queue.put(None)

    def transcripts(self) -> Iterator[str]:
        self.start()
        try:
            while True:
                item = self._transcript_queue.get()
                if item is None:
                    break
                yield item
        finally:
            self.stop()


def stream_microphone_transcripts(
    language: str = "en-US",
    sample_rate: int = 16000,
    channels: int = 1,
) -> Iterator[str]:
    transcriber = StreamingMicrophoneTranscriber(
        language=language, sample_rate=sample_rate, channels=channels
    )
    return transcriber.transcripts()


if __name__ == "__main__":
    try:
        for transcript in stream_microphone_transcripts():
            print(transcript)
    except KeyboardInterrupt:
        sys.exit(0)
